#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=9

ENV_FILE=".env.local"
PROJECT_NAME="exchange-gift"
VERCEL=(vercel)
command -v vercel >/dev/null 2>&1 || VERCEL=(npx -y vercel@65.10.0)

cd "$(git rev-parse --show-toplevel 2>/dev/null || dirname "$0")"

banner "Deploy Gift Exchange to Vercel"

# ── Stage 1 ────────────────────────────────────────────────────────────────
stage "Check tools, branch and database settings"
for tool in git gh pnpm node npx curl; do
  if ! command -v "$tool" >/dev/null 2>&1; then
    warn "$tool is not installed. Install it, then re-run this wizard."
    exit 1
  fi
done
say "git, gh, pnpm, node, npx and curl are installed."
if [[ "$(git branch --show-current)" != "main" || -n "$(git status --porcelain)" ]]; then
  warn "Switch to a clean main branch first (commit or stash your changes), then re-run."
  exit 1
fi
say "You're on main with no uncommitted changes."
for key in DATABASE_URL DATABASE_URL_UNPOOLED; do
  if [[ -z "$(_existing "$key" || true)" ]]; then
    warn "$key is missing from $ENV_FILE. Run scripts/setup-neon.sh first."
    exit 1
  fi
done
say "$ENV_FILE has the Neon connection strings. They're never printed."
pause

# ── Stage 2 ────────────────────────────────────────────────────────────────
stage "Put the code on GitHub"
if ! gh auth status >/dev/null 2>&1; then
  step "Sign in to GitHub in the browser that opens."
  gh auth login --web
fi
if git remote get-url origin >/dev/null 2>&1; then
  say "This repo already has a GitHub remote: $(git remote get-url origin)"
else
  say "This creates a private GitHub repository named \"$PROJECT_NAME\" under your account."
  if ! confirm "Create it now?"; then
    warn "Stopped before creating anything. Re-run when you're ready."
    exit 1
  fi
  gh repo create "$PROJECT_NAME" --private --source . --remote origin
fi
git push -u origin main
REPO_NAME=$(basename -s .git "$(git remote get-url origin)")
printf '  %s✓ pushed%s main to GitHub\n' "$GREEN" "$RESET"
pause

# ── Stage 3 ────────────────────────────────────────────────────────────────
stage "Sign in to Vercel"
if "${VERCEL[@]}" whoami >/dev/null 2>&1; then
  say "You're already signed in to Vercel as $("${VERCEL[@]}" whoami 2>/dev/null)."
else
  step "Sign in (or create a free Hobby account) in the browser that opens."
  step "Come back here once the terminal says you're logged in."
  "${VERCEL[@]}" login
fi
pause

# ── Stage 4 ────────────────────────────────────────────────────────────────
stage "Create the Vercel project"
if [[ -f .vercel/project.json ]]; then
  say "This folder is already linked to a Vercel project; reusing it."
else
  say "This creates (or reuses) a Vercel project named \"$PROJECT_NAME\" in your default team"
  say "and links this folder to it. The link lives in .vercel/, which git ignores."
  if ! confirm "Create and link it now?"; then
    warn "Stopped before creating anything. Re-run when you're ready."
    exit 1
  fi
  "${VERCEL[@]}" link --yes --project "$PROJECT_NAME"
fi
note "vercel.json pins the functions to Singapore (sin1), next to the Neon database."
pause

# ── Stage 5 ────────────────────────────────────────────────────────────────
stage "Connect the GitHub repository"
say "Vercel needs its GitHub app installed on your account to see the private repo."
open_url "https://github.com/apps/vercel/installations/new"
step "Pick your account, choose \"Only select repositories\", add \"$REPO_NAME\", then Install."
step "If it's already installed, check \"$REPO_NAME\" is in its repository list and Save."
pause "Press Enter once the Vercel app can see the repo"
# The CLI exits 1 when the repo is already connected, which is the state we want.
if ! connect_output=$("${VERCEL[@]}" git connect --yes 2>&1); then
  if [[ "$connect_output" != *"already connected"* ]]; then
    printf '%s\n' "$connect_output"
    warn "Vercel couldn't connect the repo. Check the GitHub app can see it, then re-run."
    exit 1
  fi
fi
printf '  %s✓ connected%s %s to the Vercel project\n' "$GREEN" "$RESET" "$REPO_NAME"
note "From now on, every push to main deploys to production by itself."
pause

# ── Stage 6 ────────────────────────────────────────────────────────────────
stage "Give production its database"
say "Copying DATABASE_URL from $ENV_FILE into Vercel's production environment as a"
say "sensitive variable. It's piped straight across, never shown or saved elsewhere."
note "Preview deployments get no database URL, so they can't touch real data."
_existing DATABASE_URL | "${VERCEL[@]}" env add DATABASE_URL -e production --sensitive --force --yes >/dev/null
printf '  %s✓ set%s DATABASE_URL (production, sensitive)\n' "$GREEN" "$RESET"
printf '1' | "${VERCEL[@]}" env add ENABLE_EXPERIMENTAL_COREPACK -e production --force --yes >/dev/null
printf '  %s✓ set%s ENABLE_EXPERIMENTAL_COREPACK=1 (builds use the pnpm version package.json pins)\n' "$GREEN" "$RESET"
pause

# ── Stage 7 ────────────────────────────────────────────────────────────────
stage "Create the tables in the production database"
say "This runs the Drizzle migrations against Neon's main branch (DATABASE_URL_UNPOOLED)."
note "Already-applied migrations are skipped, so re-running is safe."
if confirm "Migrate the production database now?"; then
  pnpm db:migrate
  printf '  %s✓ migrated%s the production database\n' "$GREEN" "$RESET"
else
  SKIPPED+=("Production migrations (run: pnpm db:migrate)")
  warn "Skipped. The site won't work until you run: pnpm db:migrate"
fi
pause

# ── Stage 8 ────────────────────────────────────────────────────────────────
stage "Deploy to production"
say "This builds the app on Vercel and publishes it. It takes a couple of minutes."
if ! confirm "Deploy now?"; then
  warn "Stopped before deploying. Re-run, or push to main, when you're ready."
  exit 1
fi
"${VERCEL[@]}" deploy --prod --yes
pause

# ── Stage 9 ────────────────────────────────────────────────────────────────
stage "Check the live site"
open_url "https://vercel.com/dashboard"
step "Open \"$PROJECT_NAME\" and copy its production domain (like $PROJECT_NAME-xyz.vercel.app)."
ask PRODUCTION_URL "Production URL:"
PRODUCTION_URL="https://${PRODUCTION_URL#https://}"
PRODUCTION_URL="${PRODUCTION_URL%/}"
if curl -fsS "$PRODUCTION_URL/" | grep -q "Gift Exchange"; then
  printf '  %s✓ landing page%s loads\n' "$GREEN" "$RESET"
else
  SKIPPED+=("Landing page check failed: open $PRODUCTION_URL and check the Vercel logs")
  warn "The landing page didn't load as expected."
fi
if curl -fsS "$PRODUCTION_URL/join/ZZZZ-ZZZZ" | grep -q "no Exchange with that code"; then
  printf '  %s✓ database%s answers (a made-up Access Code is looked up and not found)\n' "$GREEN" "$RESET"
else
  SKIPPED+=("Database check failed: check DATABASE_URL and the migrations, then the Vercel runtime logs")
  warn "The Access Code lookup didn't answer as expected."
fi
pause

finish
note "Live at $PRODUCTION_URL. Pushes to main deploy automatically from now on."
}

run_wizard "$@"; exit
